#!/usr/bin/env python3
"""Generates the stress fixtures (they are too big to keep as hand-written text).

    python3 tools/gen_stress.py today        # writes today/big_sweep.rox and today/long_run.rox

These have no .expected files: they exist to be timed, not compared.
"""
import sys, os

root = sys.argv[1] if len(sys.argv) > 1 else "today"

values = ", ".join(repr(round(0.001 + i * 0.0019, 6)) for i in range(1000))
with open(os.path.join(root, "big_sweep.rox"), "w") as f:
    f.write(f"""-- fixture: big_sweep
-- role: stress
-- status: runnable today
-- oracle: the thermostat swept over 1000 values of k, 200 steps each: 1000 jobs, 201000 rows.
--         No golden output; time it. Every job with 0 < k < 2 converges towards 20.
--         (Generated by tools/gen_stress.py.)
-- compare: none

param setpoint: float = 20
param k: float = 0.5

state Room {{ temp: float }}

step Heating:
    input:
        heat: float = k * (setpoint - s.temp)
    mechanism:
        temp: s.temp + u.heat

system Thermostat: Room = Heating

run Thermostat from Room {{ temp: 10 }} for 200 steps
    sweep k in [{values}]
""")

with open(os.path.join(root, "long_run.rox"), "w") as f:
    f.write("""-- fixture: long_run
-- role: stress
-- status: runnable today
-- oracle: one job, 200000 steps of the thermostat. No golden output; time it.
--         The last row is 20 (k = 0.5 converges to the setpoint).
-- compare: none

param setpoint: float = 20
param k: float = 0.5

state Room { temp: float }

step Heating:
    input:
        heat: float = k * (setpoint - s.temp)
    mechanism:
        temp: s.temp + u.heat

system Thermostat: Room = Heating

run Thermostat from Room { temp: 10 } for 200000 steps
""")
